/* ======= Clips: load and play only when on screen ======= */
(function(){
  var vids = Array.prototype.slice.call(document.querySelectorAll("video[data-m]"));
  /* where each clip starts: the hero reel does not start at 0 but at the first frame of the shot nearest to 12 s before its end
     (the shot starts at 107.000 s of 118.583 s; 107.02 s is the middle of its first frame, so it never lands on the black frame before it) */
  var START_AT = {reel: 107.02};
  function startOf(v){ return START_AT[v.getAttribute("data-m")] || 0; }
  vids.forEach(function(v){
    var k = v.getAttribute("data-m");
    if(POSTERS[k]) v.poster = POSTERS[k];
    v.muted = true; v.setAttribute("muted","");
    v.addEventListener("loadedmetadata", function(){ var st = startOf(v); if(st && !v.__st){ v.__st = true; try{ v.currentTime = st; }catch(e){} } });   /* the reel opens on its chosen shot, once */
    v.addEventListener("playing", function(){ v.classList.add("on"); });
    v.addEventListener("loadeddata", function(){ v.classList.add("on"); });
  });
  /* phones: the clips that are seen together use a lighter version (same frames, same speed, smaller picture); the single big clips stay as they are */
  var LIGHT = innerWidth < 700 && typeof MEDIA_M !== "undefined";
  function load(v){ if(!v.getAttribute("src")){ var k=v.getAttribute("data-m"), src = (LIGHT && MEDIA_M[k]) ? MEDIA_M[k] : MEDIA[k]; if(src) v.src = src; } }
  function play(v){ load(v); if(reduced){ v.classList.add("on"); return; } var p = v.play(); if(p && p.catch) p.catch(function(){ v.classList.add("on"); }); }
  if(!("IntersectionObserver" in window)){ vids.forEach(play); return; }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      var v = en.target;
      if(en.isIntersecting){ if(document.body.classList.contains("live")) play(v); else load(v); }
      else if(!v.paused){ v.pause(); }          /* it stops out of view and picks up from the same point when it comes back */
    });
  },{rootMargin:"120px 0px",threshold:0.05});
  vids.forEach(function(v){ io.observe(v); });
  window.__startClips = function(){
    vids.forEach(function(v){ var r = v.getBoundingClientRect(); if(r.bottom > -120 && r.top < innerHeight + 120) play(v); });
  };
})();



/* ======= The name spans the full width of its frame (same width as the black hole behind it) ======= */
(function(){
  var h = document.getElementById("heroName"), box = document.querySelector(".hero-panel .hero-text"); if(!h || !box) return;
  function fit(){
    var cs = getComputedStyle(box), inner = box.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
    h.style.fontSize = "100px"; var w = h.scrollWidth; if(!w) return;
    h.style.fontSize = (100 * inner / w).toFixed(2) + "px";
  }
  fit(); addEventListener("resize", fit); addEventListener("load", fit);
  if(document.fonts && document.fonts.ready) document.fonts.ready.then(fit);
})();


/* ======= Left-to-right wipe for the important paragraphs ======= */
(function(){
  var els = Array.prototype.slice.call(document.querySelectorAll("main .sec-head, main .glass, main .syn"));
  els.forEach(function(e){ e.classList.add("wipe"); });
  if(reduced || !("IntersectionObserver" in window)){ els.forEach(function(e){ e.classList.add("in"); }); return; }
  var io = new IntersectionObserver(function(en){ en.forEach(function(x){ if(x.isIntersecting){ x.target.classList.add("in"); io.unobserve(x.target); } }); }, {threshold:.18});
  els.forEach(function(e){ io.observe(e); });
})();




/* ======= Glass and vignette without banding: the same gradients as the CSS, computed per pixel with half a level
   of random dither and drawn once into a canvas (on large screens at reduced resolution). The CSS stays as a fallback. ======= */
